/**
 * Get human-readable Title Case item name from numeric ID
 */
function getItemNameFromNumericId(id) {
  if (id === null || id === undefined) return "Unknown Item";
  const str = String(id).trim();
  return MINECRAFT_NUMERIC_IDS[str] || MINECRAFT_NUMERIC_IDS[parseInt(str, 10)] || "Unknown Item";
}

/**
 * Safe resolve item name for Minecraft inventory slots
 */
function resolveItemName(id, damage = 0) {
  const name = getItemNameFromNumericId(id);
  return name !== "Unknown Item" ? name : String(id);
}

/**
 * Get raw namespaced identifier (e.g. "trpixel:aspect_of_the_dragons" or "minecraft:stone")
 */
function getItemIdentifier(id) {
  if (id === null || id === undefined) return null;
  const str = String(id).trim();
  return NUMERIC_ITEM_IDENTIFIERS[str] || NUMERIC_ITEM_IDENTIFIERS[parseInt(str, 10)] || null;
}

const getItemIdentifierFromNumericId = getItemIdentifier;

// Browser Globals
if (typeof window !== "undefined") {
  window.MINECRAFT_NUMERIC_IDS = MINECRAFT_NUMERIC_IDS;
  window.NUMERIC_ITEM_IDS = NUMERIC_ITEM_IDS;
  window.NUMERIC_ITEM_IDENTIFIERS = NUMERIC_ITEM_IDENTIFIERS;
  window.getItemNameFromNumericId = getItemNameFromNumericId;
  window.resolveItemName = resolveItemName;
  window.getItemIdentifier = getItemIdentifier;
  window.getItemIdentifierFromNumericId = getItemIdentifierFromNumericId;
}

// Node.js Module Exports
if (typeof module !== "undefined" && module.exports) {
  module.exports = {
    MINECRAFT_NUMERIC_IDS,
    NUMERIC_ITEM_IDS,
    NUMERIC_ITEM_IDENTIFIERS,
    getItemNameFromNumericId,
    resolveItemName,
    getItemIdentifier,
    getItemIdentifierFromNumericId
  };
}
